using System.Windows.Controls;
using System.Windows.Media;

namespace System.Windows;

/// <summary>
/// The three hooks code generated by the XAML source generator uses on <see cref="FrameworkElementFactory"/>: SetCreator (a node is
/// created by code, not by Activator.CreateInstance, which NativeAOT cannot do for a constructor nobody calls), SetInitializer (code
/// that runs on each created node) and SetAttacher (how a node becomes part of a parent that does not take it through IAddChild, as
/// Track takes its Thumb). A factory without them behaves exactly as before.
/// </summary>
public class FrameworkElementFactoryTests
{
    // Activator.CreateInstance(typeof(NoDefaultConstructor)) throws: only a creator can make one.
    public sealed class NoDefaultConstructor : FrameworkElement
    {
        public NoDefaultConstructor(int unused) { }
    }

    // Not IAddChild: a child node can only get in through an attacher.
    public sealed class Host : FrameworkElement
    {
        public FrameworkElement? Part { get; set; }
    }

    private static T Apply<T>(FrameworkElementFactory root, out Control control, out ControlTemplate template) where T : DependencyObject
    {
        template = new ControlTemplate(typeof(Control)) { VisualTree = root };
        control = new Control { Template = template };
        control.ApplyTemplate();
        return (T)VisualTreeHelper.GetChild(control, 0);
    }

    [Fact]
    public void ACreator_MakesTheNode_WithoutTheActivator()
    {
        int created = 0;
        var root = new FrameworkElementFactory(typeof(NoDefaultConstructor));
        root.SetCreator(() => { created++; return new NoDefaultConstructor(1); });

        var node = Apply<NoDefaultConstructor>(root, out _, out _);

        created.Should().Be(1);
        node.Should().BeOfType<NoDefaultConstructor>();
    }

    [Fact]
    public void ACreator_SetBeforeTheType_IsNotDiscardedByTheTypeSetter()
    {
        int created = 0;
        var root = new FrameworkElementFactory();
        root.SetCreator(() => { created++; return new NoDefaultConstructor(1); });
        root.Type = typeof(NoDefaultConstructor);

        var node = Apply<NoDefaultConstructor>(root, out _, out _);

        created.Should().Be(1);
        node.Should().BeOfType<NoDefaultConstructor>();
    }

    [Fact]
    public void AnInitializer_RunsOnEveryNodeTheFactoryCreates()
    {
        int initialized = 0;
        var root = new FrameworkElementFactory(typeof(Border));
        root.SetInitializer(node => { initialized++; ((FrameworkElement)node).Tag = "initialized"; });
        var template = new ControlTemplate(typeof(Control)) { VisualTree = root };

        var first = new Control { Template = template };
        var second = new Control { Template = template };
        first.ApplyTemplate();
        second.ApplyTemplate();

        initialized.Should().Be(2);
        ((FrameworkElement)VisualTreeHelper.GetChild(first, 0)).Tag.Should().Be("initialized");
        ((FrameworkElement)VisualTreeHelper.GetChild(second, 0)).Tag.Should().Be("initialized");
    }

    [Fact]
    public void AnAttacher_PutsANamedChildNodeIntoAParentThatIsNotIAddChild()
    {
        var part = new FrameworkElementFactory(typeof(Border), "part");
        part.SetAttacher((parent, child) => ((Host)parent).Part = (FrameworkElement)child);
        var root = new FrameworkElementFactory(typeof(Host));
        root.AppendChild(part);

        var host = Apply<Host>(root, out var control, out var template);

        host.Part.Should().BeOfType<Border>();
        // still a node of the template: found by name, which is what a trigger's TargetName needs
        template.FindName("part", control).Should().BeSameAs(host.Part);
    }

    [Fact]
    public void AChildWithoutAnAttacher_StillNeedsAParentThatIsIAddChild()
    {
        var root = new FrameworkElementFactory(typeof(Host));
        root.AppendChild(new FrameworkElementFactory(typeof(Border)));
        var template = new ControlTemplate(typeof(Control)) { VisualTree = root };

        Action seal = () => template.Seal();

        seal.Should().Throw<InvalidOperationException>();
    }

    [Fact]
    public void ATextChild_NeedsAParentThatIsIAddChild_EvenWithAnAttacher()
    {
        // Text is added with IAddChild.AddText, which an attacher cannot replace: Seal must not admit it for a non-IAddChild parent.
        var text = new FrameworkElementFactory("some text");
        text.SetAttacher((_, _) => { });
        var root = new FrameworkElementFactory(typeof(Host));
        root.AppendChild(text);
        var template = new ControlTemplate(typeof(Control)) { VisualTree = root };

        Action seal = () => template.Seal();

        seal.Should().Throw<InvalidOperationException>();
    }

    [Fact]
    public void TheHooks_CannotBeSetOnceTheTemplateIsSealed()
    {
        var root = new FrameworkElementFactory(typeof(Border));
        var template = new ControlTemplate(typeof(Control)) { VisualTree = root };
        template.Seal();

        ((Action)(() => root.SetCreator(() => new Border()))).Should().Throw<InvalidOperationException>();
        ((Action)(() => root.SetInitializer(_ => { }))).Should().Throw<InvalidOperationException>();
        ((Action)(() => root.SetAttacher((_, _) => { }))).Should().Throw<InvalidOperationException>();
    }
}
